/// The methods of Mesh.
pub trait MeshExt {
    /// Fails when an index runs past the vertices. Every other mesh call skips such a triangle.
    fn check(&self) -> Result<(), MathError>;
    fn distance(&self, point: Double3) -> f64;
    fn closest(&self, point: Double3) -> SurfacePoint;
    /// 1 when the triangles of a closed mesh wind round the point, which puts it inside.
    fn contains(&self, point: Double3) -> bool;
    fn raycast(&self, ray: Ray) -> Option<RayHit>;
    fn bounds(&self) -> AlignedBox;
    fn area(&self) -> f64;
    /// What a closed mesh holds, from the signed solids its triangles make with one point. The centroid
    /// is of that volume, or of the surface when the mesh holds none.
    fn volume(&self) -> f64;
    fn centroid(&self) -> Double3;
    fn inertia(&self, mass: f64) -> Inertia;
    /// The unit normal at each vertex, the sum of its triangles' normals by their area, NaN for a
    /// vertex in none. normals holds vertex_count.
    fn normals(&self) -> Result<Vec<Double3>, MathError>;
    fn to_shape(&self) -> Shape<'_>;
}

