/// The methods of Image.
pub trait ImageExt {
    fn check(&self) -> Result<(), MathError>;
    /// A pixel as a colour. Mono16 and Monof32 hold measurements, which only colorize shows.
    fn color_at(&self, x: u32, y: u32) -> Result<Color, MathError>;
    /// The number in a pixel of Mono8, Mono16 or Monof32.
    fn value_at(&self, x: u32, y: u32) -> Result<f64, MathError>;
    /// Mono8 from colour is BT.601 luma, and alpha is dropped or opaque.
    fn convert(&self, format: ImageFormat) -> Result<Image, MathError>;
    fn colorize(&self, low: f64, high: f64, ramp: &[Color], format: ImageFormat) -> Result<Image, MathError>;
    /// Not Nv12, and Yuyv keeps whole pairs.
    fn crop(&self, x: u32, y: u32, width: u32, height: u32) -> Result<Image, MathError>;
    fn flip_horizontal(&self) -> Result<Image, MathError>;
    fn flip_vertical(&self) -> Result<Image, MathError>;
    /// Clockwise as seen on screen, any number of quarter turns.
    fn rotate(&self, quarter_turns: i32) -> Result<Image, MathError>;
    fn resize(&self, filter: ImageFilter, width: u32, height: u32) -> Result<Image, MathError>;
    /// A pixel no source reaches is 0, NaN in Monof32.
    fn undistort(&self, camera: &CameraIntrinsics, ideal: Option<&CameraIntrinsics>, filter: ImageFilter) -> Result<Image, MathError>;
    /// A shape in pixels blended over Mono8, Rgb8, Rgba8 or Bgr8 with a smooth edge. width 0 fills,
    /// above 0 draws the outline that wide, and a curve with no inside is drawn 1 wide for 0.
    fn draw(&mut self, shape: &Shape2D, color: Color, width: f64) -> Result<(), MathError>;
    /// NaN where the depth is 0 or not finite. Sizes must match.
    fn depth_points(&self, camera: &CameraIntrinsics) -> Result<Vec<Double3>, MathError>;
}

